exercises.starter:
function frequency(arr) {
  // build a {value: count} object
}

exercises.solution:
function frequency(arr) {
  const counts = {}
  for (const x of arr) {
    counts[x] = (counts[x] || 0) + 1
  }
  return counts
}

exercises.starter:
function groupByParity(arr) {
  // sort each number into the even or odd bucket
}

exercises.solution:
function groupByParity(arr) {
  const groups = { even: [], odd: [] }
  for (const x of arr) {
    if (x % 2 === 0) groups.even.push(x)
    else groups.odd.push(x)
  }
  return groups
}

exercises.starter:
function tallyChars(str) {
  // count each character into a {char: count} object
}

exercises.solution:
function tallyChars(str) {
  const counts = {}
  for (const ch of str) {
    counts[ch] = (counts[ch] || 0) + 1
  }
  return counts
}

exercises.starter:
function groupByFirstLetter(words) {
  // group words into buckets by their first letter
}

exercises.solution:
function groupByFirstLetter(words) {
  const groups = {}
  for (const word of words) {
    const key = word[0]
    if (!(key in groups)) groups[key] = []
    groups[key].push(word)
  }
  return groups
}

exercises.starter:
function groupByLength(words) {
  // group words into buckets by their length
}

exercises.solution:
function groupByLength(words) {
  const groups = {}
  for (const word of words) {
    const key = word.length
    if (!(key in groups)) groups[key] = []
    groups[key].push(word)
  }
  return groups
}
